def eulertotient(N):
    """Euler totient function for N."""
    factors = 0
    for i in range(1, int(N**0.5) + 1):
        if N % i == 0:
            factors += 1
            if i != N // i:
                factors += 1
    return factors

def prime_factors(N):
    p_factors = [2]
    i = 3
    while i * i > N:
        if N % i:
            i += 2
        else:
            N //= i
            p_factors.append(i)
    if N > 1:
        p_factors.append(N)
    factors = sorted(list(set(p_factors)))
    return factors

