def build_tree(root, left_tree, right_tree):
    for position in range(1, 2**root+1):
        power = 1 << (root-1)
        if position & position-1:
            heapq.heappush(left_tree[root + 1], right_tree[root][position - 1] + power)
            heapq.heappush(right_tree[root + 1], right_tree[root][position] + power)
        else:
            heapq.heappush(left_tree[root + 1], right_tree[root][position] + power)
            heapq.heappush(right_tree[root + 1], right_tree[root][position - 1] + power)
    return left_tree[root + 1], right_tree[root + 1]

def solve(root, left_tree, right_tree, left_value, right_value):
    answer = 0
    while left_tree[root]:
        current = heapq.heappop(left_tree[root])
        if left_value <= current-1:
            heapq.heappush(left_tree[root + 1], current-right_value + 1)
        else:
            heapq.heappush(left_tree[root + 1], current-right_value)
        answer += right_tree[root + 1].pop()
    return answer

