from collections import deque

def bfs(r, c, n, m):
    q = deque([(r, c)])
    seen = {(r, c): 0}
    next = deque()
    level = 0
    while q:
        x, y = q.popleft()
        if x == r + 1 or x == 1 or y == m or y == 1:
            level += 1
            q = deque()
            next = deque()
            seen = {(r, c): level}
        for x, y in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
            if 1 <= x <= n and 1 <= y <= m and (x, y) not in seen:
                seen[(x, y)] = level
                next.append((x, y))
    return level + 1, seen

def count_pleasant_segments(n, m, f):
    level = n * m
    tree = [0] * (n * m)
    seen = {}
    for i in range(n):
        for j in range(m):
            f_val = f[i][j]
            for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                if a == 0 or a == n or b == 0 or b == m or f[a][b] > f_val or (a, b) in seen:
                    continue
                a_val = f[a][b]
                b_val = f_val
                tree[f_val - 1] = f[a][b]  # Join to tree or add to root as root
                tree[f[a][b] - 1] = f_val  # Renumber to max so call is possible
                seen[(i, j)] = f_val
                break
    total = 0
    for i in range(n * m):
        f_a, f_b = seen[i // 1000], seen[(i - 1) // 1000]
        if i % 1000 > 0 and i % 1000 + min(f_a, f_b) == min(f_a, f_b):
            total += 1
    return level, tree, seen, total

def count_levels(n, m, f):
    ans = 0
    for i in range(n * m):
        ans += n * i
    return ans // n // m

def count_segments(n, m):
    levels, tree, seen, chances = count_pleasant_segments(n, m, f)
    answer = 0
    for level in range(1, levels + 1):
        answer += chances - ((1 - 2 ** level) // 2) if seen[level] == 1 else ((1 - 2 ** level) // 2 + 1)
    return round(answer / (levels - 1))

