# Checks if the input string is valid
def is_valid(seq):
    balance = 0
    for char in seq:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

# Calculates the sum of depths for all valid bracket sequences
def calculate_depth_sum(seq):
    valid_sequences = [
        seq[:i] + '()' + seq[i:] for i in range(len(seq) + 1) if is_valid(seq[:i] + '()' + seq[i:])
    ]
    depth_sum = 0
    for seq in valid_sequences:
        depth_sum = (depth_sum + sum(cal_depth(pp_seq) for pp_seq in post_fixes(seq))) % MOD
    return depth_sum

# Calculates the depth of a given bracket sequence
def cal_depth(seq):
    balance = 0
    max_depth = 0
    for char in seq:
        if char == '(':
            balance += 1
            max_depth = max(max_depth, balance)
        elif char == ')':
            balance -= 1
    return max_depth

# Calculates the postfix representation of a bracket sequence
def post_fixes(seq):
    stack = []
    for char in seq:
        if char == '(':
            stack.append(char)
        elif char == ')':
            stack.pop()
    return stack

