def solve(s):
    potential_depths = defaultdict(int)
    max_depth, char_count = calculate_depths(s)

    for char in char_count:
        for depth in sorted(set(char_count[char])):
            times = char_count[char] // depth
            value = times * (depth + 1)

            for alt_depth in range(depth - 1, -1, -1):
                times = (times - 1) // alt_depth
                value += times * (alt_depth + 1)

            potential_depths[max_depth - alt_depth] += value

    return sum(v % 998244353 for v in potential_depths.values())

