# Function to check if two cells are occupied by a domino
def are_dominos_occupied(cell1, cell2):
    return board[cell1[0]][cell1[1]] in ['L', 'R'] and board[cell2[0]][cell2[1]] in ['U', 'D']

# Function to determine if a board is solvable
def is_solvable(board):
    sides = [(0, -1), (n, -1), (0, m), (n, m)]
    free_cells = [(i, j) for i in range(n) for j in range(m) if (i, j) not in domino_positions]
    sides_dominoes = {side: [pos for pos in domino_positions if are_dominos_occupied(side, pos)] for side in sides}
    if len(sides_dominoes) > 4:
        return False
    if len(free_cells) < len(sides_dominoes):
        return False

    free_board_space = [(i, j) for i in range(n) for j in range(m) if board[i][j] == ' ']
    sides_free = [(0, -1), (n, -1), (0, m), (n, m)]
    sides_reset_count = len(free_board_space) - len(sides_dominoes.keys())
    if sides_reset_count != len(free_cells):
        return False

    # Check for entanglement
    entanglement_free_pairs = [(i1, j1) for (i1, j1,) in sides_free for (i2, j2,) in sides_entangles if board[(i1, j1)] != board[(i2, j2)]]
    sides_entangles = {side: domino_positions for side, dominoes in sides_dominoes.items() for domino in domino_pairs_n_piece((dominoes, sides_entangles))]
    sides_reset_count_entangled = len(entanglement_free_pairs) - len(sides_free)
    if sides_reset_count_entangled != len(domino_positions):
        return False

    return True

# Function to get all tuples of pairs of cells the board can be put back in place if removed
def get_possible_sets():
    sides = [(0, -1), (n, -1), (0, m), (n, m)]

    left = {(cell, (cell[0], cell[1] + 1)) for cell in sides_dominoes.get((cell, (cell[0], cell[1] + 1)), {}) for side, side_indices in sides.items()}
    right = {(cell, (cell[0], cell[1] - 1)) for (cell,) in sides_dominoes.get((cell, (cell[0], cell[1] - 1)), {}) for side, side_indices in sides.items()}
    top = {(cell, (cell[0] - 1, cell[1])) for (cell,) in sides_dominoes.get((cell, (cell[0] - 1, cell[1])), {}) for side, side_indices in sides.items()}
    bottom = {(cell, (cell[0] + 1, cell[1])) for (cell,) in sides_dominoes.get((cell, (cell[0] + 1, cell[1])), {}) for side, side_indices in sides.items()}
    sets_of_pairs = (left | right | top | bottom)

    returned_pairs = {(cell[0], cell[1]) if (cell,) in sides else cell for cell in sets_of_pairs if are_dominos_occupied(cell[1], cell[0]) and are_dominos_occupied(cell[0], (cell[1] + 1, cell[1]))
                      or are_dominos_occupied(cell[1], (cell[0] - 1, cell[1])) and are_dominos_occupied(cell[1], (cell[1] - 1, cell[1]))
                      or are_dominos_occupied(cell[1], cell[0]) and are_dominos_occupied(cell[1], (cell[1] + 1, cell[1] + 1))
                      or are_dominos_occupied(cell[1], (cell[1] - 1, cell[1] + 1))}

