        edges_ascending[e[0]].append(e[1])
        edges_ascending[e[1]].append(e[0])

    def dijkstra_all(start):
        distances[start] = 0
        queue = [(0, start)]
        parents[start] = start
        while queue:
            length, node = heappop(queue)
            if length > distances[node]:
                continue
            for neighbor in edges_ascending[node]:
                if distances[node] + edge_dist[node][neighbor] < distances[neighbor]:
                    parent = parents[node]
                    parents[neighbor] = node
                    distances[neighbor] = distances[node] + edge_dist[node][neighbor]
                    heappush(queue, (distances[neighbor], neighbor))

    dijkstra_all(root)
    return distances, parents

