def k_selection(k, m):
    """选择元素的文件号数量，时间和指数之间的组合的数量】】
       分开的数量"""
    combinations = []
    for factorial in range(1, k + 1):
        for combinations in flat_map(lambda dist: star_k_combinations(factorial, m, dist), combinations_for_factorial_k(m)):

