from collections import defaultdict

def prime_factorization(N, prime_factors):
    # Euler totient function 
    def ephi(n):
        if n == 1: 
            return 1
        result = n
        p = 2
        while p * p <= n: 
            if n % p == 0: 
                count = 0
                while n % p == 0: 
                    n //= p 
                    count += 1 
                result *= p**(count - 1)
            p += 1
        if n > 1: 
            result *= (p - 1) * (p**((1 - count % p) % p) - 1) 
        return result

    # Finding prime factors of 'N' using efficient factorization
    p = 2 
    factors = defaultdict(int)
    while p * p <= N: 
        if N % p == 0: 
            factors[p] = 1
            N //= p
        else: 
            p += 1
    if N > 1: 
        factors[N] = 1
    prime_factors.append(factors)

def calculate_prime_factors(N, phi, prime_factors):
    p = sorted(prime_factors, key=lambda x: len(x.keys())*x[1], reverse=True)
    for factor in p:
        # Calculating Euler function again to find n-th solution
        n = (N - phi) // sum(factor.values()) 
        # Unpack factor objects
        prime, raise = zip(*factor.items())
        for p_opt, e_opt in zip(prime, [int(float(e_opt)) for e_opt in raise]):
            while n >= e_opt:
                n -= e_opt
                factor[p_opt] = e_opt
            if n == phi // sum(factor.values()):
                return factor

def euler_totient_function(N, prime_factors):
    # Euler totient function for number
    def eos(n):
        result = 1
        p = 2
        while p * p <= n: 
            if n % p == 0: 
                count = 0
                while n % p == 0: 
                    n //= p 
                    count += 1 
                result *= n**(count - 1)
            else: 
                p += 1
        if n > 1: 
            result *= n**(-1)  
        return result

