MOD = 998244353
mod = 998244353

def power(x, n):
    if n == 0:
        return 1
    if n % 2 == 0:
        half_power = power(x, int(n / 2))
        return half_power * half_power % mod
    else:
        return x * power(x, n - 1) % mod

def inverse(x):
    if x < 0:
        return mod - mod // x
    return power(x, mod - 2) % mod

def factorial(n):
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % mod
    return result

def binomial_coefficient(n, k):
    return factorial(n) * inverse(factorial(k)) * inverse(factorial(n - k)) % MOD

def count_valid_sequences(s):
    left_count = 0
    right_count = 0
    for char in s:
        if char == '(':
            left_count += 1
        elif char == ')':
            right_count += 1
        else:
            right_count += 1  # '?' character
            left_count += 1
    return (left_count + right_count) * (left_count + right_count) % mod

