    split_indices = [(i, input_string[i]) for i in range(1, string_length) if input_string[i] == '?']
    for (split_index, char) in split_indices:
        input_string = input_string[:split_index] + char + input_string[split_index + 1:]
    string_length = len(input_string)
    if string_length < 6:
        return dp(string_length, 3)

    max_depth = 1
    for char in input_string:
        if char == '?':
