        elif char == '(':
            max_depth = max(max_depth, dp(string_length - 1, (max_depth + 1) % 2))
        elif char == ')':
            max_depth = max(max_depth, 1 + dp(string_length - 1 - 2, (max_depth - 1 + 1) % 2))
        else:
            raise ValueError('Invalid character')

    return (998244353 - max_depth) % 998244353

