def edit_distance(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n+1) for _ in range(m+1)]
    for i in range(m+1):
        dp[i][0] = i
    for j in range(n+1):
        dp[0][j] = j
    for i in range(1, m+1):
        for j in range(1, n+1):
            if a[i-1] == b[j-1]:
                dp[i][j] = min(dp[i-1][j-1], dp[i][j-1], dp[i-1][j]) + 1
            else:
                dp[i][j] = min(dp[i-1][j-1], dp[i][j-1], dp[i-1][j]) + 1
    return dp[-1][-1]

def k_news(portfolio, k):
    portfolio.sort()
    result = 0
    for day in days:
        if day == k:
            return result
        for day0 in reversed(range(k)):
            days_used = k - day0
            if portfolio[portfolio.index(day0)-1] + days_used <= day:
                result += portfolio[portfolio.index(day0)-1] * days_used
                break
    return result

