import math

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def euler_totient_function(n):
    return n * math.prod(1 - 1/p for p in prime_factors(n)) if n > 1 else 1

def find_factors(n):
    factors = set()
    for i in range(n + 1):
        if gcd(i, n) == 1:
            factors.add(i)
    return sorted(factors)

