                exit = (i, j)
            elif maze[i][j] == 'X':
                hero = (i, j)
                hero_found = True

    if not hero_found:
        print("No solution")
        return

    dist = [[float('inf')] * m for _ in range(n)]
    dist[hero[0]][hero[1]] = 0
    q = deque([(hero[0], hero[1], 0)])

    while q:
        i, j, dist_ij = q.popleft()
        for di, dj in [(-1, 0), (0, -1), (1, 0), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m and dist[ni][nj] > dist_ij + 1:
                dist[ni][nj] = dist_ij + 1
                if maze[ni][nj] == 'X':
                    q.append((ni, nj, dist_ij + 3))
                elif maze[ni][nj] == 'E':
                    return " ".join(['S'] * dist_ij + ['M'] + ['S'] * dist_ij + ['N'] * (3 - dist_ij))
                elif maze[ni][nj] == 'T':
                    q.append((ni, nj, dist_ij + 2))

    return "No solution"

