from collections import defaultdict

def remove_domino(board):
    """Remove a random Domino that leaves at least 2 free cells."""
    valid_moves = []
    for x, y in moves(board):
        valid_moves.append((x, y))
    if not valid_moves:
        return (False, False, False)
    move_index = min(valid_moves, key=lambda x: moves(board)[x])
    row, col = move_index
    for shift in [row + 1, row - 1]:
        for j in [col + 1, col - 1]:
            if board[shift][j] == ' ' or board[shift][j] == '_':
                return (False, False, ((shift, j), (shift, j)))
    domino_to_remove = (row, col)
    board[domino_to_remove[0]][domino_to_remove[1]] = ' '
    first_free_cell_direction = board[domino_to_remove[0]][domino_to_remove[1] - 1]
    second_free_cell_direction = board[domino_to_remove[0]][domino_to_remove[1] + 1]
    board[domino_to_remove[0]][domino_to_remove[1] - 1] = '_'
    board[domino_to_remove[0]][domino_to_remove[1] + 1] = '_'
    return (True, (first_free_cell_direction + 1, domino_to_remove[1]), (second_free_cell_direction - 1, domino_to_remove[1]))

def moves(board):
    """Get all valid cell shifts where a domino could potentially be moved."""
