def get_hero_moves(maze, hero, exit):
    directions = {"S": [0, 1], "N": [0, -1], "E": [1, 0], "W": [-1, 0]}
    for y in range(len(maze)):
        for x in range(len(maze[0])):
            if maze[y][x] == "E":
                hero_exit = (y, x)
            elif maze[y][x] == "T":
                target = (y, x)
            if hero == target:
                m, n = y, x

    moves = []
    count = 0
    while (m, n) != hero_exit:
        # check the directions for the next move
        for direction, (dy, dx) in directions.items():
            newy, newx, trip = m + dy, n + dx, False

            # move towards the next character in the direction
            while (newy not in [0, len(maze) - 1]) and (newx not in [0, len(maze[0]) - 1]) and (maze[newy][newx] in "X.T") and not trip:
                moves.append(direction)
                trip = True
                count += 1

                # reset (newy, newx) if we hit starting position
                if newy in [0, len(maze) - 1] or newx in [0, len(maze[0]) - 1]:
                    newy -= 6 if direction == "S" else -6
                    moves.append("M")  # plant a bomb in the previous position as we triggered a trip

                    # add the step count to the step number to avoid run-time errors
                    if count % 3 == 0:
                        step = count // 3
                    else:
                        step = (count // 3 - 1) * 3 + 3 * count % 3

                    count = step
                    if count > 100000 and count % 3 != 0:
                        break
                    elif count > 100000:
                        moves.append('M')
                    trip = False

                newy += dy
                newx += dx
                count += 1

    if count > 100000 and count % 3 != 0:
        moves.append('M')

    return moves


def main():
    n, m = map(int, input().split())
    maze = [input() for _ in range(n)]
    hero = tuple(map(lambda x: x == "E", maze).index(True))
    exit = tuple(map(lambda x: x == "T", maze).index(True))

    moves = get_hero_moves(maze, hero, exit)
    moves = ' '.join(moves)
    print(f"{moves}\nUse Standard Input format")


if __name__ == "__main__":
    main()

