from bisect import bisect_left

def construct_tree(nums):
    tree = {}
    for i in range(len(nums)):
        parent = int("".join(map(str, nums[i:2*(i+1)])))
        tree[parent] = i+1
    return tree

def get_tree(parents):
    tree_depth = {1: 0}
    n = 0
    for k in parents:
        n += 1
        tree_depth[k] = n
        parents[k // 2] = k
    return tree_depth

def get_depth_and_value_from_trie(depth_tree, value):
    ans = []
    nodes = [i+1 for i in range(len(depth_tree))]
    for i in range(value-1, 0, -1):
        idx = bisect_left(nodes, i)
        curr = depth_tree[idx//2]
        ans.append((depth_tree[idx], nodes[idx]))
        nodes[idx] = nodes[curr//2]
    return len(depth_tree) - nodes.index(get_depth_and_value_from_trie(depth_tree, value)[0])

