from math import factorial

def calculate_ways(n, k, m):
    # Subtract 1 to avoid using the start planet itself
    ordered_ways = k
    total_ways = 1

    # Calculate the maximum k that can be achieved with the given m
    max_achievable_k = min(k, (2 * m + 1 - 1)) // (m + 1)

    # If Neko can visit up to (2 * m + 1 - 1) planets, we immediately get the result
    if max_achievable_k >= k:
        return ordered_ways

    # Adjust k to fit within the maximum achievable in m
    k = min(k, max_achievable_k)

    if k == 1:
        return factorial(n - 1)
    else:
        # Using inclusion-exclusion principle to calculate the ways
        for i in range(1, k):
            if factorial(n) > (k - i) * pow(factorial(n - i), m + 1, 10 ** 9 + 7):
                factor = k - i
                total_ways = total_ways * pow(factorial(n) // (factorial(n - i) * pow(factorial(n - i), m + 1)), 10 ** 9 + 7, 10 ** 9 + 7) - pow(factorial(n), 10 ** 9 + 7, 10 ** 9 + 7)
        return total_ways % (10 ** 9 + 7)

