from math import gcd
from typing import List

def lcm(x: int, y: int) -> int:
    return x * y // gcd(x, y)

def find_max_r_squared(points: List[List[int]]) -> int:
    num_points = len(points)

    def gcd_tuples(tuples):
        a, b, c = tuples
        return [(a, gcd(a, b)), (b, gcd(b, c)), (c, gcd(c, a))]

    points_gcd = set(gcd_tuples(tuple(map(gcd, points[i], points[i+1], points[i+2]))) for i in range(num_points))
    points_gcd = list(points_gcd)

    def lattice(r, vectors):
        return set(coeffs * r for coeffs in [(u, v, w) for u, v, w in vectors] for r in range(r**3))

    potential_lattices = lattice(1, points_gcd)

    valid_lattices = {r for r in range(1, int(10**16)/r) if lattice(r, points_gcd).issubset(potential_lattices)}

    return max(valid_lattices) ** 2, *[gcd(u, v, w) ** 2 for u, v, w in vectors[valid_lattices]] for vectors in sorted(valid_lattices, reverse=True)
